#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

/// Returns true if and only if `rep` is one of the scalar variants:
/// ScalarInt, ScalarFloat, ScalarComplex, ScalarBool, or ScalarString.
pub fn issctype(rep: DataType) -> bool {
    matches!(
        rep,
        DataType::ScalarInt
            | DataType::ScalarFloat
            | DataType::ScalarComplex
            | DataType::ScalarBool
            | DataType::ScalarString
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_issctype_scalars() {
        assert!(issctype(DataType::ScalarInt));
        assert!(issctype(DataType::ScalarFloat));
        assert!(issctype(DataType::ScalarComplex));
        assert!(issctype(DataType::ScalarBool));
        assert!(issctype(DataType::ScalarString));
    }

    #[test]
    fn test_issctype_non_scalars() {
        assert!(!issctype(DataType::ArrayType));
        assert!(!issctype(DataType::CompositeType));
        assert!(!issctype(DataType::UnknownType));
    }
}